    tiling.set_num_cores(tiling_strategy.num_cores);
    tiling.set_blocks_per_core(tiling_strategy.blocks_per_core);

    // 7. 设置优化参数
    tiling.set_double_buffer_size(calculate_double_buffer_size(tiling_strategy));
    tiling.set_vectorization_width(select_vectorization_width(tiling_strategy));
    tiling.set_enable_pipeline(should_enable_pipeline(tiling_strategy));

    // 8. 序列化并保存
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                       context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 9. 设置BlockDim
    context->SetBlockDim(tiling_strategy.num_cores);
    return ge::GRAPH_SUCCESS;
}

// 注册Tiling函数
REGISTER_TILING_FUNC(DynamicSoftmaxOp, DynamicSoftmaxTilingFunc);

// 优化策略计算
TilingStrategy compute_optimal_tiling_strategy(uint32_t total_elements,
                                              uint32_t dim_size,
                                              uint32_t inner_size,
                                              uint32_t available_cores,
                                              uint32_t ub_size) {
    TilingStrategy strategy;
    // 考虑Softmax计算特性：需要沿dim_size进行归约
    strategy.num_cores = calculate_optimal_core_count(total_elements, dim_size,
                                                     available_cores, ub_size);

    // 计算每个核心的工作量
    uint32_t elements_per_core = total_elements / strategy.num_cores;

    // 基于UB容量和计算特性确定分块大小
    strategy.tile_size = calculate_optimal_tile_size(elements_per_core, dim_size,
                                                     inner_size, ub_size);

    // 计算分块数量
    strategy.num_tiles = (elements_per_core + strategy.tile_size - 1) / strategy.tile_size;
    strategy.last_tile_size = elements_per_core % strategy.tile_size;
    if (strategy.last_tile_size == 0) {
        strategy.last_tile_size = strategy.tile_size;
    }

    strategy.blocks_per_core = strategy.num_tiles;
    return strategy;
}

} // namespace optiling
