```cpp
// softmax_tiling.cpp - Host侧Tiling计算
#include "softmax_tiling.h"
#include "platform_ascendc.h"

namespace optiling {

ge::graphStatus DynamicSoftmaxTilingFunc(gert::TilingContext* context) {
    // 1. 获取输入形状信息
    auto input_shape = context->GetInputTensor(0)->GetShape();
    auto input_dims = input_shape.GetDims();

    // 2. 获取算子属性（Softmax维度）
    int64_t softmax_dim;
    context->GetAttr("softmax_dim", &softmax_dim);

    // 3. 计算Softmax相关维度
    uint32_t outer_size = 1, dim_size = 1, inner_size = 1;
    for (int64_t i = 0; i < softmax_dim; ++i) {
        outer_size *= input_dims[i];
    }
    dim_size = input_dims[softmax_dim];
    for (int64_t i = softmax_dim + 1; i < input_shape.GetDimNum(); ++i) {
        inner_size *= input_dims[i];
    }
    uint32_t total_elements = outer_size * dim_size * inner_size;

    // 4. 获取硬件信息
    auto platform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());
    uint32_t available_cores = platform.GetCoreNumAic();
    uint32_t ub_size = platform.GetUbSize();

    // 5. 计算最优分块策略
    DynamicSoftmaxTiling tiling;
    auto tiling_strategy = compute_optimal_tiling_strategy(
        total_elements, dim_size, inner_size, available_cores, ub_size);

    // 6. 设置Tiling参数
    tiling.set_total_elements(total_elements);
    tiling.set_dim_size(dim_size);
    tiling.set_inner_size(inner_size);
    tiling.set_outer_size(outer_size);
    tiling.set_tile_size(tiling_strategy.tile_size);
    tiling.set_num_tiles(tiling_strategy.num_tiles);
    tiling.set_last_tile_size(tiling_strategy.last_tile_size);
    tiling.set_num_cores(tiling_strategy.num_cores);
    tiling.set_blocks_per_core(tiling_strategy.blocks_per_core);

    // 7. 设置优化参数
    tiling.set_double_buffer_size(calculate_double_buffer_size(tiling_strategy));
    tiling.set_vectorization_width(select_vectorization_width(tiling_strategy));
    tiling.set_enable_pipeline(should_enable_pipeline(tiling_strategy));

    // 8. 序列化并保存
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                       context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 9. 设置BlockDim
    context->SetBlockDim(tiling_strategy.num_cores);
    return ge::GRAPH_SUCCESS;
}

// 注册Tiling函数
REGISTER_TILING_FUNC(DynamicSoftmaxOp, DynamicSoftmaxTilingFunc);

// 优化策略计算
TilingStrategy compute_optimal_tiling_strategy(uint32_t total_elements,
                                              uint32_t dim_size,
                                              uint32_t inner_size,
                                              uint32_t available_cores,
                                              uint32_t ub_size) {
    TilingStrategy strategy;
    // 考虑Softmax计算特性：需要沿dim_size进行归约
    strategy.num_cores = calculate_optimal_core_count(total_elements, dim_size,
                                                     available_cores, ub_size);

    // 计算每个核心的工作量
    uint32_t elements_per_core = total_elements / strategy.num_cores;

    // 基于UB容量和计算特性确定分块大小
    strategy.tile_size = calculate_optimal_tile_size(elements_per_core, dim_size,
                                                     inner_size, ub_size);

    // 计算分块数量
    strategy.num_tiles = (elements_per_core + strategy.tile_size - 1) / strategy.tile_size;
    strategy.last_tile_size = elements_per_core % strategy.tile_size;
    if (strategy.last_tile_size == 0) {
        strategy.last_tile_size = strategy.tile_size;
    }

    strategy.blocks_per_core = strategy.num_tiles;
    return strategy;
}

} // namespace optiling
